import {sessionStats,exerciseStats} from './training-stats.mjs';
import {WORKOUT_NAMES} from './training.mjs';
import {renderExerciseGuide} from './exercise-guide-ui.mjs';
import {defaultRestSeconds} from './rest-timer.mjs';

const trainingEscape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function trainingSetLabel(row){
  return row.status==='completed'?(row.targetMet?'已完成 · 次数达标':'已完成 · 次数低于计划'):({empty:'未记录',recorded:'已填写 · 待确认',skipped:'已跳过 · 不计完成',invalid:'数值无效',partial:'记录不完整'}[row.status]);
}
export function renderTrainingSet(ex,index,set={}){
  const row=exerciseStats(ex,Array.from({length:ex.sets},(_,i)=>i===index?set:null)).rows[index];
  return `<div class="set-row actual-set ${row.completed?'finished':''} ${set.skipped?'skipped-set':''}" id="set-${ex.id}-${index}">
    <div class="set-card-head"><b>第 ${index+1} 组</b><span data-set-status>${trainingSetLabel(row)}</span></div>
    <div class="set-inputs">${[['kg','重量 kg',0,500,.5],['reps','实际次数',1,100,1],['rir','余力次数（选填）',0,10,1]].map(([field,label,min,max,step])=>`<label class="field">${label}<input type="number" inputmode="${field==='reps'?'numeric':'decimal'}" aria-label="${trainingEscape(ex.name)}第${index+1}组${label}" min="${min}" max="${max}" step="${step}" placeholder="${field==='kg'?'自重填0':field==='rir'?'可留空':'实做次数'}" value="${trainingEscape(set[field]??'')}" data-kind="set" data-ex="${ex.id}" data-set="${index}" data-field="${field}" ${set.skipped?'disabled':''}></label>`).join('')}</div>
    <p class="set-error" role="status"></p><p class="set-calculation" data-set-calculation></p>
    <div class="set-actions"><label class="complete-set"><input type="checkbox" aria-label="完成${trainingEscape(ex.name)}第${index+1}组" data-kind="set-done" data-ex="${ex.id}" data-set="${index}" ${row.completed?'checked':''} ${set.skipped?'disabled':''}>完成本组</label><button class="secondary rest-start" data-action="rest-start" data-ex="${ex.id}" data-seconds="${defaultRestSeconds(ex)}" ${!row.completed?'hidden':''}>休息 ${defaultRestSeconds(ex)} 秒</button><button class="text-button" data-action="skip-set" data-ex="${ex.id}" data-set="${index}">${set.skipped?'恢复记录':'跳过本组'}</button>${index?`<button class="text-button copy-set" data-action="copy-set" data-ex="${ex.id}" data-set="${index}" ${set.skipped?'disabled':''}>沿用上一组重量</button>`:''}</div>
    <label class="field skip-reason" ${!set.skipped?'hidden':''}>跳过原因（选填）<input type="text" maxlength="200" placeholder="如：器械占用、疲劳或不适" value="${trainingEscape(set.skipReason||'')}" data-kind="skip-reason" data-ex="${ex.id}" data-set="${index}"></label>
  </div>`;
}
export function renderTrainingPage(v){
  const {p,type,exs,data,preview,readOnly,stage,time,feedback,previous}=v;
  if(!type)return `<section class="card rest-panel"><h2>${p.active?'今天没有力量训练':'这一天不在训练计划内'}</h2><p class="reading mt">正常走动、按同样菜单吃，留出恢复时间。${p.walk?`计划快走${p.walk}分钟。`:''}</p><a class="secondary mt" href="#today">回今日记录</a></section>`;
  const stats=sessionStats(exs,data),f=data.trainingFeedback||{},locked=!!data.trainingPlan;
  const choices=[['1','每动作1组 · 适应'],['2','每动作最多2组'],['3','完整组数 · 2–3组']];
  return `${preview?`<section class="card preview-card"><p class="eyebrow">EXPLORE YOUR TRAINING LOG</p><h2>开始前，先看记录界面</h2><p class="micro-note">下方是空白预览，不保存、不计入真实完成度。准备好后点击上方“开始计划”。</p><div class="field-grid mt"><label class="field">预览训练日<select id="training-preview-type">${['UA','LA','UB','LB'].map(t=>`<option value="${t}" ${type===t?'selected':''}>${WORKOUT_NAMES[t]}</option>`).join('')}</select></label><label class="field">预览组数<select id="training-preview-level">${choices.map(([n,label])=>`<option value="${n}" ${stage===Number(n)?'selected':''}>${label}</option>`).join('')}</select></label></div></section>`:readOnly?'<div class="notice">当前是只读记录。暂停期间不记录新训练；继续计划后可填写当前训练日。</div>':''}
    <section class="card session-card mt" aria-label="本次实际训练量"><div class="training-toolbar"><div><p class="eyebrow">${trainingEscape(WORKOUT_NAMES[type])} · ${trainingEscape(time)}</p><h2>每一组，按实际记录</h2><p class="micro-note" id="session-state"></p></div><div class="session-percentage"><b id="session-percent">${stats.percent}%</b><span>执行完成率</span></div></div><div class="track mt" role="progressbar" aria-label="本次训练完成度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${stats.percent}" id="training-progressbar"><span id="training-progress"></span></div><p class="micro-note" id="training-count"></p><div class="training-metrics"><div><b id="metric-exercises">0/${exs.length}</b><span>动作全部完成</span></div><div><b id="metric-reps">—</b><span>实际累计次数</span></div><div><b id="metric-load">—</b><span>负荷指数 · kg×次</span></div><div><b id="metric-target">—</b><span>已完成组中次数达标</span></div></div><p class="micro-note" id="session-detail"></p><details class="metric-explanation"><summary>完成度怎么算？</summary><p>有效重量＋实际次数＋手动确认完成，才计入完成组。次数低于计划仍算实际完成，另显示次数达标率。跳过不计完成，填写后未勾选也不计完成。</p><p>负荷指数仅将已完成组的标记重量×次数相加，不是热量或肌肉增长。自重填0；哑铃填单只重量。同一器械、同一记法才适合比较，不同动作和器械的数字不能直接比较。</p></details></section>
    <section class="card mt"><fieldset class="training-fieldset" ${readOnly?'disabled':''}><div class="training-toolbar"><div><h3>本次目标</h3><p class="micro-note">热身不计正式组。首次请工作人员教你调器械；留2–3次规范余力。</p></div><label class="field">正式组数档位<select id="set-level" ${locked?'disabled':''}>${choices.map(([n,label])=>`<option value="${n}" ${stage===Number(n)?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="micro-note" id="plan-lock-note">${locked?'已锁定本次计划组数；做不完可以如实跳过，完成率保留实际情况。':'确认完成或跳过第一组后，锁定本次目标组数。'}</p></fieldset></section>
    <div class="stack mt training-exercises">${exs.map((ex,i)=>{const es=stats.exercises[ex.id],prior=previous(ex.id);return `<details class="card exercise training-exercise" data-exercise="${ex.id}" ${i===Math.max(0,exs.findIndex(e=>stats.exercises[e.id].percent<100))?'open':''}><summary class="exercise-header"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div class="exercise-meta"><h3>${trainingEscape(ex.name)}</h3><p>${ex.sets}组 × ${ex.min}–${ex.max}次 · 休息${trainingEscape(ex.rest)}</p></div><span class="exercise-completion" data-ex-percent="${ex.id}">${es.completedSets}/${es.plannedSets}组 · ${es.percent}%</span></summary><div class="exercise-content">${renderExerciseGuide(ex)}<p class="exercise-info">${trainingEscape(ex.tip)}</p><p class="exercise-actual" data-ex-actual="${ex.id}"></p><fieldset class="training-fieldset" ${readOnly?'disabled':''}><p class="exercise-feedback">${trainingEscape(feedback(ex))}</p>${prior?`<button class="secondary previous-weight" data-action="copy-previous" data-ex="${ex.id}">补上次重量（仅填空白）</button>`:''}<div class="sets">${Array.from({length:ex.sets},(_,j)=>renderTrainingSet(ex,j,data.sets?.[ex.id]?.[j]||{})).join('')}</div><div class="exercise-notes"><label class="field">动作备注（选填）<textarea rows="2" maxlength="500" placeholder="如：器械座椅第3档、动作感受" data-kind="exercise-note" data-ex="${ex.id}">${trainingEscape(data.exerciseNotes?.[ex.id]||'')}</textarea></label><button class="text-button" data-action="skip-remaining" data-ex="${ex.id}">剩余未完成组全部跳过</button></div></fieldset></div></details>`;}).join('')}</div>
    <section class="card mt session-feedback"><fieldset class="training-fieldset" ${readOnly?'disabled':''}><p class="eyebrow">YOUR SESSION, AS IT HAPPENED</p><h2>记录本次真实状态</h2><div class="field-grid mt"><label class="field">实际训练时长 · 分钟<input type="number" inputmode="numeric" min="0" max="600" step="1" placeholder="未计时可留空" value="${trainingEscape(f.minutes??'')}" data-kind="training-feedback" data-field="minutes"></label><label class="field">整次费力程度 · 1–10<input type="number" inputmode="numeric" min="1" max="10" step="1" placeholder="1轻松，10极费力" value="${trainingEscape(f.effort??'')}" data-kind="training-feedback" data-field="effort"></label><label class="field">训练后的感受<select data-kind="training-feedback" data-field="feeling">${[['','未记录'],['normal','恢复正常'],['tired','明显疲劳'],['sore','肌肉酸痛'],['discomfort','关节或其他不适']].map(([key,label])=>`<option value="${key}" ${f.feeling===key?'selected':''}>${label}</option>`).join('')}</select></label></div><label class="field mt">本次备注<textarea rows="3" maxlength="1000" placeholder="如：提前结束的原因、下次需要调整的地方" data-kind="training-feedback" data-field="note">${trainingEscape(f.note||'')}</textarea></label><p class="micro-note">尖锐关节痛时停止相应动作。时长按实记录，不需要为了凑满一小时加练。</p><button class="primary wide mt" data-action="finish-training" id="finish-training">${f.finished?'继续记录本次训练':'结束本次训练'}</button><p class="micro-note">结束只保存本次结果；未做的组不会变成完成，也不会暂停12周计划。可再次继续记录。</p></fieldset></section>`;
}
